import { isPlainObject, isTimestamp } from "./events";
import { canDecide } from "./hitl";
import { isSettlingTurnAction, transitionApproval, transitionDelivery, transitionTurn } from "./machines";
import { checkPlanUpdate } from "./plan";
import { checkSuggestionItems, type SuggestionsEntry } from "./suggestions";
import type { UndoEntry } from "./undo";
import type { Actor, ApprovalRecord, ChatEvent, DeliveryState, Part, QuestionRecord, TurnOutcome, TurnState } from "./types";

export interface MessageEntry {
  id: string;
  role: string;
  author: Actor | null;
  turnId: string | null;
  parts: Part[];
  /** Ids of parts still streaming. */
  open: string[];
  delivery: DeliveryState | null;
  supersedes: string | null;
  retracted: boolean;
  superseded: boolean;
}

export interface TurnEntry {
  turnId: string;
  state: TurnState;
  outcome: TurnOutcome | null;
  reason: string | null;
  /**
   * The human message that started this turn (`turn.started` `data.messageId`,
   * when that message is in the log), so a host can retry a failed turn with its
   * original input. Null for a turn no message started.
   */
  messageId: string | null;
}

export interface ThinkingEntry {
  /**
   * One run may think several times, between tool calls. Each block has its own id:
   * the event's `data.thinkingId` when it sends one, else the run id for the run's
   * first block and `<runId>#2`, `#3`... for the next.
   */
  thinkingId: string;
  runId: string;
  text: string;
  live: boolean;
}

export interface ToolEntry {
  toolCallId: string;
  runId: string | null;
  name: string;
  args: Record<string, unknown>;
  startedAt: string | null;
  progress: { fraction: number | null; text: string | null } | null;
  outcome: "ok" | "failure" | "refusal" | null;
  durationMs: number | null;
  /**
   * False when the backend could only bound the duration, not measure it (e.g. a
   * Prism Harness step timed across a process hop): render it as "at most".
   */
  durationExact: boolean;
  outputRef: string | null;
  truncated: boolean;
  /**
   * The result's text inline, as the tool or its failure wrote it (a failure's own
   * words, not a generic "failed"). Plain text: render it as text or code, NEVER as
   * HTML. The server bounds it and sets `truncated`; `outputRef` points at the rest.
   */
  output: string | null;
  /** Set when the output is code (e.g. "json"), for a code view; null means plain text. */
  outputLanguage: string | null;
}

export interface PlanStep {
  id: string;
  title: string;
  status: "pending" | "running" | "held" | "done" | "failed" | "skipped";
  owner: "agent" | "human";
  approvalId?: string;
}

export interface PlanEntry {
  runId: string;
  steps: PlanStep[];
}

export type RowKind = "message" | "thinking" | "tool" | "plan" | "approval" | "question" | "undo";

/**
 * Edit-and-resend: the rows between a superseded message and the one that
 * replaced it. The projection records the branch; the HOST's policy decides
 * what happens to it (branch, the default: keep it, shown on demand; truncate:
 * the server retracts its messages).
 */
export interface BranchEntry {
  supersededId: string;
  byId: string;
  rowIds: string[];
}

/**
 * The whole projected thread as plain JSON. This IS the snapshot format: a
 * `thread.reset` carries one, and the PHP twin produces the same shape.
 */
export interface ThreadState {
  lastSeq: number;
  /** Events refused by the machines or the human-only rule. Diagnostics, never state. */
  illegal: number;
  order: { kind: RowKind; id: string }[];
  messages: MessageEntry[];
  turns: TurnEntry[];
  thinking: ThinkingEntry[];
  tools: ToolEntry[];
  plans: PlanEntry[];
  approvals: ApprovalRecord[];
  questions: QuestionRecord[];
  undos: UndoEntry[];
  branches: BranchEntry[];
  /**
   * Quick replies for the newest turn, once it settled `completed`; null when there
   * are none. Set by `suggestions.updated`, cleared by the next `turn.started`.
   */
  suggestions: SuggestionsEntry | null;
}

export type Row =
  | ({ kind: "message" } & MessageEntry)
  | ({ kind: "thinking"; id: string } & ThinkingEntry)
  | ({ kind: "tool"; id: string } & ToolEntry)
  | ({ kind: "plan"; id: string } & PlanEntry)
  | { kind: "approval"; id: string; approvalId: string; state: ApprovalRecord["state"] }
  | { kind: "question"; id: string; questionId: string; state: NonNullable<QuestionRecord["state"]> }
  | ({ kind: "undo"; id: string } & UndoEntry);

export function emptyThreadState(): ThreadState {
  return { lastSeq: 0, illegal: 0, order: [], messages: [], turns: [], thinking: [], tools: [], plans: [], approvals: [], questions: [], undos: [], branches: [], suggestions: null };
}

const NO_RUN = "_";

function clone<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T;
}

/**
 * A decision or answer counts only when the event's actor is a human AND the
 * recorded decider is that same human. A body naming a human, carried by an
 * agent's event, is a forgery and is refused.
 */
function decidedByActor(event: ChatEvent, claimed: unknown): boolean {
  return canDecide(event.actor) && isPlainObject(claimed) && claimed.kind === event.actor.kind && claimed.id === event.actor.id;
}

const byId = <T>(list: T[], key: keyof T, id: unknown): T | undefined => list.find((x) => x[key] === id);

/**
 * Applies one event to the state, in place. Idempotent: an event at or below
 * `lastSeq` changes nothing. Returns whether the event was applied (legal or
 * not). An illegal event bumps `illegal` and leaves every entry untouched.
 *
 * Total: it never throws. A malformed event the checks below do not anticipate
 * is counted illegal and the cursor moves past it, exactly as for an illegal
 * transition. A throw would escape into the client's transport, which reads it
 * as a failed request and retries the same batch forever.
 */
export function applyEvent(state: ThreadState, event: ChatEvent): boolean {
  if (event.seq <= state.lastSeq) return false;
  try {
    return reduce(state, event);
  } catch {
    state.illegal += 1;
    state.lastSeq = event.seq;
    return true;
  }
}

function reduce(state: ThreadState, event: ChatEvent): boolean {
  const data = (isPlainObject(event.data) ? event.data : {}) as Record<string, unknown>;
  const illegal = () => {
    state.illegal += 1;
  };

  switch (event.type) {
    case "thread.snapshot":
    case "thread.reset": {
      const snap = data.snapshot;
      if (!isPlainObject(snap)) {
        illegal();
        break;
      }
      Object.assign(state, emptyThreadState(), clone(snap));
      break;
    }

    case "message.created": {
      const m = data.message;
      if (!isPlainObject(m) || typeof m.id !== "string" || byId(state.messages, "id", m.id)) {
        illegal();
        break;
      }
      const supersedes = typeof m.supersedes === "string" ? m.supersedes : null;
      state.messages.push({
        id: m.id,
        role: typeof m.role === "string" ? m.role : "assistant",
        author: isPlainObject(m.author) ? (clone(m.author) as unknown as Actor) : clone(event.actor),
        turnId: typeof data.turnId === "string" ? data.turnId : (event.turnId ?? null),
        parts: Array.isArray(m.parts) ? (clone(m.parts) as Part[]) : [],
        open: [],
        delivery: typeof m.delivery === "string" ? (m.delivery as DeliveryState) : null,
        supersedes,
        retracted: false,
        superseded: false,
      });
      const targetAt = supersedes ? state.order.findIndex((o) => o.kind === "message" && o.id === supersedes) : -1;
      if (supersedes) {
        const target = byId(state.messages, "id", supersedes);
        if (target) target.superseded = true;
      }
      if (supersedes && targetAt >= 0) {
        state.branches.push({ supersededId: supersedes, byId: m.id, rowIds: state.order.slice(targetAt + 1).map((o) => o.id) });
      }
      state.order.push({ kind: "message", id: m.id });
      break;
    }

    case "message.updated": {
      const msg = byId(state.messages, "id", data.messageId);
      if (!msg || !Array.isArray(data.parts)) {
        illegal();
        break;
      }
      msg.parts = clone(data.parts) as Part[];
      msg.open = msg.open.filter((id) => msg.parts.some((p) => p.id === id));
      break;
    }

    case "message.retracted": {
      const msg = byId(state.messages, "id", data.messageId);
      if (!msg) illegal();
      else msg.retracted = true;
      break;
    }

    case "delivery.changed": {
      const msg = byId(state.messages, "id", data.messageId);
      const next = msg && msg.delivery !== null && typeof data.action === "string" ? transitionDelivery(msg.delivery, data.action) : null;
      if (!msg || !next || !next.ok) illegal();
      else msg.delivery = next.to;
      break;
    }

    case "part.started": {
      const msg = byId(state.messages, "id", data.messageId);
      const part = data.part;
      if (!msg || !isPlainObject(part) || typeof part.id !== "string" || msg.parts.some((p) => p.id === part.id)) {
        illegal();
        break;
      }
      msg.parts.push(clone(part) as Part);
      msg.open.push(part.id);
      break;
    }

    case "part.delta": {
      const msg = byId(state.messages, "id", data.messageId);
      const index = msg ? msg.parts.findIndex((p) => p.id === data.partId) : -1;
      if (!msg || index < 0) {
        illegal();
        break;
      }
      const current = msg.parts[index] as Part;
      if (current.kind === "text" && typeof data.text === "string") {
        current.text = String(current.text ?? "") + data.text;
      } else if (isPlainObject(data.part)) {
        msg.parts[index] = { ...(clone(data.part) as Part), id: current.id };
      } else {
        illegal();
      }
      break;
    }

    case "part.completed": {
      const msg = byId(state.messages, "id", data.messageId);
      if (!msg || !msg.parts.some((p) => p.id === data.partId)) illegal();
      else msg.open = msg.open.filter((id) => id !== data.partId);
      break;
    }

    case "thinking.started":
    case "thinking.delta":
    case "thinking.completed": {
      const runId = event.runId ?? NO_RUN;
      if (data.thinkingId !== undefined && typeof data.thinkingId !== "string") {
        illegal();
        break;
      }
      const explicit = typeof data.thinkingId === "string" ? data.thinkingId : null;
      // Without an explicit id: the run's newest block, unless it has completed and this
      // event opens new thinking (started or delta). That is how one run's thinking
      // interleaves with its tool calls: each stretch is its own block, in order.
      const ofRun = state.thinking.filter((t) => t.runId === runId);
      const latest = ofRun.length > 0 ? ofRun[ofRun.length - 1] : undefined;
      let entry = explicit !== null ? byId(state.thinking, "thinkingId", explicit) : latest && (latest.live || event.type === "thinking.completed") ? latest : undefined;
      if (!entry) {
        if (event.type === "thinking.completed") {
          illegal();
          break;
        }
        const thinkingId = explicit ?? (ofRun.length === 0 ? runId : `${runId}#${ofRun.length + 1}`);
        if (byId(state.thinking, "thinkingId", thinkingId)) {
          illegal();
          break;
        }
        entry = { thinkingId, runId, text: "", live: true };
        state.thinking.push(entry);
        state.order.push({ kind: "thinking", id: thinkingId });
      }
      if (event.type === "thinking.started") entry.live = true;
      else if (event.type === "thinking.delta" && typeof data.text === "string") entry.text += data.text;
      else if (event.type === "thinking.completed") entry.live = false;
      break;
    }

    case "tool.called": {
      if (typeof data.toolCallId !== "string" || typeof data.name !== "string" || byId(state.tools, "toolCallId", data.toolCallId)) {
        illegal();
        break;
      }
      state.tools.push({
        toolCallId: data.toolCallId,
        runId: event.runId ?? null,
        name: data.name,
        args: isPlainObject(data.args) ? clone(data.args) : {},
        startedAt: typeof data.startedAt === "string" ? data.startedAt : null,
        progress: null,
        outcome: null,
        durationMs: null,
        durationExact: true,
        outputRef: null,
        truncated: false,
        output: null,
        outputLanguage: null,
      });
      state.order.push({ kind: "tool", id: data.toolCallId });
      break;
    }

    case "tool.progress": {
      const tool = byId(state.tools, "toolCallId", data.toolCallId);
      if (!tool) {
        illegal();
        break;
      }
      tool.progress = {
        fraction: typeof data.fraction === "number" ? data.fraction : null,
        text: typeof data.text === "string" ? data.text : null,
      };
      break;
    }

    case "tool.result": {
      const tool = byId(state.tools, "toolCallId", data.toolCallId);
      if (!tool || (data.outcome !== "ok" && data.outcome !== "failure" && data.outcome !== "refusal")) {
        illegal();
        break;
      }
      tool.outcome = data.outcome;
      tool.durationMs = typeof data.durationMs === "number" ? data.durationMs : null;
      tool.durationExact = data.durationExact !== false;
      tool.outputRef = typeof data.outputRef === "string" ? data.outputRef : null;
      tool.truncated = data.truncated === true;
      tool.output = typeof data.output === "string" ? data.output : null;
      tool.outputLanguage = typeof data.outputLanguage === "string" ? data.outputLanguage : null;
      break;
    }

    case "plan.updated": {
      if (!Array.isArray(data.steps)) {
        illegal();
        break;
      }
      const runId = event.runId ?? NO_RUN;
      let plan = byId(state.plans, "runId", runId);
      // A held step releases only through its approval.
      if (!checkPlanUpdate(plan?.steps ?? [], data.steps as PlanStep[], state.approvals).ok) {
        illegal();
        break;
      }
      if (!plan) {
        plan = { runId, steps: [] };
        state.plans.push(plan);
        state.order.push({ kind: "plan", id: runId });
      }
      plan.steps = clone(data.steps) as PlanStep[];
      break;
    }

    case "turn.started": {
      if (typeof data.turnId !== "string" || byId(state.turns, "turnId", data.turnId)) {
        illegal();
        break;
      }
      const origin = typeof data.messageId === "string" ? byId(state.messages, "id", data.messageId) : undefined;
      state.turns.push({ turnId: data.turnId, state: "pending", outcome: null, reason: null, messageId: origin ? origin.id : null });
      // And the other way: the message learns its turn, unless it already named one.
      if (origin && origin.turnId === null) origin.turnId = data.turnId;
      // Quick replies belong to the turn they follow; a new turn retires them.
      state.suggestions = null;
      break;
    }

    case "turn.transition":
    case "turn.settled": {
      const turn = byId(state.turns, "turnId", data.turnId);
      const action = typeof data.action === "string" ? data.action : "";
      // Only turn.settled settles a turn; a transition never may.
      const settling = isSettlingTurnAction(action);
      if (!turn || settling !== (event.type === "turn.settled")) {
        illegal();
        break;
      }
      const next = transitionTurn(turn.state, action);
      if (!next.ok) {
        illegal();
        break;
      }
      turn.state = next.to;
      turn.outcome = next.outcome;
      turn.reason = typeof data.reason === "string" ? data.reason : next.reason;
      break;
    }

    case "approval.requested": {
      const a = data.approval;
      if (!isPlainObject(a) || typeof a.approvalId !== "string" || byId(state.approvals, "approvalId", a.approvalId)) {
        illegal();
        break;
      }
      state.approvals.push({ ...(clone(a) as unknown as ApprovalRecord), state: "pending" });
      state.order.push({ kind: "approval", id: a.approvalId });
      break;
    }

    case "approval.decided": {
      const record = byId(state.approvals, "approvalId", data.approvalId);
      if (!record || !decidedByActor(event, data.decidedBy) || typeof data.decision !== "string") {
        illegal();
        break;
      }
      const from = record.state === "pending" ? transitionApproval("pending", "begin-decision") : { ok: true as const, to: record.state };
      const next = from.ok ? transitionApproval(from.to, data.decision) : from;
      if (!next.ok) {
        illegal();
        break;
      }
      record.state = next.to;
      record.decision = data.decision as ApprovalRecord["decision"];
      record.decidedBy = clone(data.decidedBy) as Actor;
      record.optionId = typeof data.optionId === "string" ? data.optionId : null;
      record.note = typeof data.note === "string" ? data.note : null;
      break;
    }

    case "approval.applied": {
      const record = byId(state.approvals, "approvalId", data.approvalId);
      const next = record ? transitionApproval(record.state, data.ok === true ? "apply" : "apply-fail") : null;
      if (!record || !next || !next.ok) {
        illegal();
        break;
      }
      record.state = next.to;
      record.error = typeof data.error === "string" ? data.error : null;
      break;
    }

    case "approval.withdrawn": {
      const record = byId(state.approvals, "approvalId", data.approvalId);
      const next = record ? transitionApproval(record.state, data.expired === true ? "expire" : "withdraw") : null;
      if (!record || !next || !next.ok) illegal();
      else record.state = next.to;
      break;
    }

    case "question.asked": {
      const q = data.question;
      if (!isPlainObject(q) || typeof q.questionId !== "string" || byId(state.questions, "questionId", q.questionId)) {
        illegal();
        break;
      }
      state.questions.push({ ...(clone(q) as unknown as QuestionRecord), state: "open" });
      state.order.push({ kind: "question", id: q.questionId });
      break;
    }

    case "question.answered": {
      const q = byId(state.questions, "questionId", data.questionId);
      if (!q || q.state !== "open" || !decidedByActor(event, data.answeredBy)) {
        illegal();
        break;
      }
      q.state = "answered";
      q.answeredBy = clone(data.answeredBy) as Actor;
      q.values = isPlainObject(data.values) ? clone(data.values) : {};
      q.notes = isPlainObject(data.notes) ? (clone(data.notes) as Record<string, string>) : {};
      break;
    }

    case "undo.opened": {
      if (typeof data.actionId !== "string" || typeof data.label !== "string" || !isTimestamp(data.deadline) || byId(state.undos, "actionId", data.actionId)) {
        illegal();
        break;
      }
      state.undos.push({ actionId: data.actionId, label: data.label, deadline: data.deadline, state: "open" });
      state.order.push({ kind: "undo", id: data.actionId });
      break;
    }

    case "undo.committed":
    case "undo.reverted": {
      const entry = byId(state.undos, "actionId", data.actionId);
      // Only the human reverts; the host (or its timer) commits.
      const allowed = event.type === "undo.committed" || decidedByActor(event, data.revertedBy);
      if (!entry || entry.state !== "open" || !allowed) {
        illegal();
        break;
      }
      entry.state = event.type === "undo.committed" ? "committed" : "reverted";
      break;
    }

    case "suggestions.updated": {
      // Only for the NEWEST turn, settled completed, and never from a human: a
      // suggestion is offered to the person, it is not something a person sets.
      const last = state.turns.length > 0 ? state.turns[state.turns.length - 1] : undefined;
      const checked = checkSuggestionItems(data.items);
      if (
        event.actor.kind === "human" ||
        typeof data.turnId !== "string" ||
        !last ||
        last.turnId !== data.turnId ||
        last.outcome !== "completed" ||
        !checked.ok
      ) {
        illegal();
        break;
      }
      state.suggestions = checked.items.length > 0 ? { turnId: data.turnId, items: checked.items } : null;
      break;
    }

    default:
      // Runs, usage, agent status, handoff and x-* events carry no row.
      break;
  }

  state.lastSeq = event.seq;
  return true;
}

/**
 * Under the truncate policy, the turns a removed branch must cancel: every
 * UNSETTLED turn the branch references, through a message in it (the
 * superseded message included) or an approval placed in it. In `state.turns`
 * order. Settled turns and turns outside the branch are never touched.
 */
export function turnsToCancelForBranch(state: ThreadState, supersededId: string): string[] {
  const branch = (state.branches ?? []).find((b) => b.supersededId === supersededId);
  if (!branch) return [];
  const ids = new Set([supersededId, ...branch.rowIds]);
  const referenced = new Set<string>();
  for (const m of state.messages) if (ids.has(m.id) && m.turnId) referenced.add(m.turnId);
  for (const a of state.approvals) if (ids.has(a.approvalId) && typeof a.turnId === "string") referenced.add(a.turnId);
  return state.turns.filter((t) => t.state !== "settled" && referenced.has(t.turnId)).map((t) => t.turnId);
}

/** The rows a thread renders, in order of first appearance. */
export function rowsOf(state: ThreadState): Row[] {
  const rows: Row[] = [];
  for (const { kind, id } of state.order) {
    if (kind === "message") {
      const m = byId(state.messages, "id", id);
      if (m) rows.push({ kind, ...m });
    } else if (kind === "thinking") {
      const t = byId(state.thinking, "thinkingId", id);
      if (t) rows.push({ kind, id, ...t });
    } else if (kind === "tool") {
      const t = byId(state.tools, "toolCallId", id);
      if (t) rows.push({ kind, id, ...t });
    } else if (kind === "plan") {
      const p = byId(state.plans, "runId", id);
      if (p) rows.push({ kind, id, ...p });
    } else if (kind === "approval") {
      const a = byId(state.approvals, "approvalId", id);
      if (a) rows.push({ kind, id, approvalId: a.approvalId, state: a.state });
    } else if (kind === "question") {
      const q = byId(state.questions, "questionId", id);
      if (q) rows.push({ kind, id, questionId: q.questionId, state: q.state ?? "open" });
    } else if (kind === "undo") {
      const u = byId(state.undos, "actionId", id);
      if (u) rows.push({ kind, id, ...u });
    }
  }
  return rows;
}

export interface ThreadProjection {
  lastSeq: number;
  illegal: number;
  rows: Row[];
  turns: TurnEntry[];
  approvals: ApprovalRecord[];
  questions: QuestionRecord[];
  /** `state.suggestions`: the newest settled turn's quick replies, or null. */
  suggestions: SuggestionsEntry | null;
  state: ThreadState;
}

/** Pure: folds events, in the order given, into the projected thread. */
export function projectThread(events: readonly ChatEvent[], initial?: ThreadState): ThreadProjection {
  const state = initial ? clone(initial) : emptyThreadState();
  for (const event of events) applyEvent(state, event);
  return { lastSeq: state.lastSeq, illegal: state.illegal, rows: rowsOf(state), turns: state.turns, approvals: state.approvals, questions: state.questions, suggestions: state.suggestions ?? null, state };
}
